import ui_draw as _d
import ui_fonts as _f

WIDTH = 320
HEIGHT = 240

DEFAULTS = {
    "humidity": 50,  # int, 0…100
    "temperature": 10.0,  # float, -20…40
    "alarm": False,  # bool
}


class UI(_d.Page):
    BACKGROUND = 0xC408  # #0b1a22
    DEFAULTS = DEFAULTS
    USES_ALPHA = True  # a second region buffer for translucent widgets
    # (id, x, y, w, h, parameters) in layer order: the first one is the lowest.
    WIDGETS = (
        ("dial", 20, 20, 161, 161, ()),
        ("needle", 100, 100, 72, 2, ("humidity",)),
        ("hub", 94, 94, 13, 13, ()),
        ("h_txt", 70, 140, 71, 24, ("humidity",)),
        ("word", 200, 30, 120, 40, ()),
        ("glass", 190, 20, 120, 60, ("alarm",)),
        ("tilt", 220, 110, 60, 30, ()),
        ("tag", 200, 160, 101, 24, ()),
        ("track", 10, 215, 302, 2, ()),
        ("marker", 4, 205, 13, 13, ("temperature",)),
    )

    def set_humidity(self, value):
        self.p["humidity"] = value
        return self.update()

    def set_temperature(self, value):
        self.p["temperature"] = value
        return self.update()

    def set_alarm(self, value):
        self.p["alarm"] = value
        return self.update()

    def _draw_dial(self, fb, ox, oy):
        _d.ellipse(fb, 20 - ox, 20 - oy, 161, 161, 0x0511)

    def _draw_needle(self, fb, ox, oy):
        # redrawn when changed: humidity
        p = self.p
        angle = 0.0
        angle = _d.lin(p["humidity"], 0, 100, -180.0, 0.0)
        r = _d.rot(angle, 100 - ox, 100 - oy)
        _d.line(fb, 100 - ox, 100 - oy, 70, 0, 0x24ED, r)

    def _box_needle(self):
        p = self.p
        angle = 0.0
        angle = _d.lin(p["humidity"], 0, 100, -180.0, 0.0)
        return _d.rbox(100, 100, 72, 2, angle, 100, 100)

    def _draw_hub(self, fb, ox, oy):
        _d.ellipse(fb, 94 - ox, 94 - oy, 13, 13, 0xFFFF)

    def _draw_h_txt(self, fb, ox, oy):
        # redrawn when changed: humidity
        p = self.p
        _d.label(
            fb,
            _d.fmt("%d%%", p["humidity"]),
            70 - ox,
            140 - oy,
            70,
            24,
            0xFFFF,
            _f.SERIF_16,
            _d.LEFT,
        )

    def _draw_word(self, fb, ox, oy):
        _d.label(fb, "ПРИВІТ", 200 - ox, 30 - oy, 120, 40, 0xFFFF, _f.SERIF_24, _d.LEFT)

    def _draw_glass(self, fb, ox, oy):
        # redrawn when changed: alarm
        p = self.p
        opacity = 50
        # conditions, top to bottom: the lowest one that matches wins
        if p["alarm"]:
            opacity = 90
        level = _d.alpha(opacity)
        if level == 0:
            return
        if level < 32:
            fb = self.begin_alpha(fb)
        _d.rrect(fb, 190 - ox, 20 - oy, 120, 60, 4, 0x4AFA)
        if level < 32:
            self.end_alpha(level)

    def _draw_tilt(self, fb, ox, oy):
        r = _d.rot(30.0, 250 - ox, 125 - oy)
        _d.rrect(fb, 220 - ox, 110 - oy, 60, 30, 4, 0x545E, r)

    def _box_tilt(self):
        return _d.rbox(220, 110, 60, 30, 30.0, 250, 125)

    def _draw_tag(self, fb, ox, oy):
        r = _d.rot(-20.0, 250 - ox, 172 - oy)
        _d.label(fb, "НАХИЛ", 200 - ox, 160 - oy, 100, 24, 0x199F, _f.SERIF_16, _d.LEFT, r)

    def _box_tag(self):
        return _d.rbox(200, 160, 101, 24, -20.0, 250, 172)

    def _draw_track(self, fb, ox, oy):
        _d.line(fb, 10 - ox, 215 - oy, 300, 0, 0x8F53)

    def _draw_marker(self, fb, ox, oy):
        # redrawn when changed: temperature
        p = self.p
        x = 4
        x = _d.lin(p["temperature"], -20.0, 40.0, 4.0, 304.0)
        x = _d.rnd(x)
        _d.ellipse(fb, x - ox, 205 - oy, 13, 13, 0x1F4D)

    def _box_marker(self):
        p = self.p
        x = 4
        x = _d.lin(p["temperature"], -20.0, 40.0, 4.0, 304.0)
        x = _d.rnd(x)
        return (x, 205, 13, 13)
